module ::Lich
  module Common
    module Jinx
      # Native package browser. Independent actions retain the original worker
      # behavior; rendering reads snapshots and never fetches a manifest.
      module GUI
        # Preserve Log.out's original body and output path. The GUI-only mirror
        # is inert when no native Browser has registered a listener.
        module LogMirror
          def out(msg, label: :debug)
            listeners = native_gui_listeners
            unless listeners.empty?
              if msg.is_a?(StandardError)
                listeners.each { |listener| listener.call("[#{label}] #{msg.message}") }
                msg.backtrace.to_a.slice(0..5).each do |frame|
                  listeners.each { |listener| listener.call(frame) }
                end
              else
                listeners.each { |listener| listener.call("[#{label}] #{msg}") }
              end
            end
            super
          end
        end

        def self.start!
          Browser.new(owner: Script.current).show.wait
        end

        class Browser
          attr_reader :page, :worker

          def initialize(owner:, catalog: Repo, actions: CLI, directories: Folder)
            @owner, @catalog, @actions, @directories = owner, catalog, actions, directories
            @mutex = Mutex.new
            @completion = Lich::WebUI::Future.new
            @repos, @assets, @selected, @filters = [], { script: [], data: [] }, {}, {}
            @logs = ["Jinx GUI initialized at #{Time.now}"]
            @info = { script: 'Select an item and click Info to see details', data: 'Select an item and click Info to see details' }
            @error = ''
            @search_text, @search_revision = {}, Hash.new(0)
            @table_pages, @table_sorts = Hash.new(0), {}
            @busy, @closed, @revision = false, false, 0
            @workers, @manifest_cache, @search_workers = [], {}, {}
          end

          def show(load: true)
            browser = self
            @page = Lich::WebUI.page(owner: @owner, id: 'jinx-browser', title: 'Jinx - Package Manager',
                                     props: { bare: true, density: :compact, viewport: true, size: [1100, 700] },
                                     on: { close: proc { close } }) { |tree| browser.send(:render, tree) }
            @log_listener = Log.observe_native_gui(method(:append_log))
            refresh
            Lich::WebUI.start
            Lich::WebUI.open(page: @page)
            perform('Refresh manifests') { refresh_data } if load
            self
          rescue StandardError
            close
            raise
          end

          def wait
            @completion.await
          ensure
            close
          end

          def close
            workers = @mutex.synchronize { @closed = true; @workers.dup }
            Log.stop_observing_native_gui(@log_listener) if @log_listener
            @log_listener = nil
            @completion.cancel
            workers.each do |worker|
              next if worker == Thread.current
              worker.kill
              worker.join
            end
            Lich::WebUI.close(@page) if @page
            nil
          end

          # Each click captures its own inputs, as the original GTK callbacks
          # did. All workers belong to this script and are stopped on close.
          def perform(label, &action)
            gate = Queue.new
            spawned = nil
            accepted = @mutex.synchronize do
              next false if @closed
              @busy = true
              @error = ''
              @worker = Thread.new do
                gate.pop
                Thread.current[:jinx_native_log] = method(:append_log)
                begin
                  action.call
                rescue StandardError => error
                  @mutex.synchronize { @error = error.message.to_s[0, 8192] }
                  append_log("#{label}: #{error.message}")
                ensure
                  Thread.current[:jinx_native_log] = nil
                  @mutex.synchronize { @workers.delete(Thread.current); @busy = !@workers.empty? }
                  refresh
                end
              end
              spawned = @worker
              @workers << @worker
              @owner.thread_group.add(@worker) if @owner.respond_to?(:thread_group)
              true
            end
            if accepted
              refresh
              gate << true
            end
            accepted
          rescue StandardError
            # Adoption or the initial refresh may fail before the gate opens.
            # Kill only this attempt's worker and clear its busy state.
            if spawned
              spawned.kill
              spawned.join
              @mutex.synchronize { @workers.delete(spawned); @busy = !@workers.empty? }
            end
            raise
          end

          def refresh_data
            repos, assets = [], { script: [], data: [] }
            @catalog.to_a.each do |repo|
              status = 'ok'
              begin
                manifest = manifest_with_retries(repo)
                @mutex.synchronize { @manifest_cache[repo[:name].to_s] = manifest }
                append_log("[WARN] #{repo[:name]} has error: #{manifest[:err]}") if manifest[:err]
                %i[script data].each do |kind|
                  assets[kind].concat(asset_rows(kind, manifest))
                end
              rescue StandardError => error
                status = "error: #{error.message}"
                append_log("#{repo[:name]}: #{status}")
                # The original refresh retains an earlier manifest when its
                # replacement fails; asset lists are rebuilt from that cache.
                cached = @mutex.synchronize { @manifest_cache[repo[:name].to_s] }
                %i[script data].each { |kind| assets[kind].concat(asset_rows(kind, cached)) } if cached
              end
              repos << { name: repo[:name].to_s, url: repo[:url].to_s, status: status }
            end
            @mutex.synchronize do
              @revision += 1
              @repos = repos.sort_by { |row| row[:name].to_s }
              @assets = assets.transform_values { |rows| rows.sort_by { |row| [row[:name].to_s, row[:repo].to_s] } }
              # GTK repopulates both full lists without clearing their entries.
              @filters.clear
              # GTK restores selection by asset name/repository, not display
              # columns such as installed or modified status.
              @selected.keys.each do |kind|
                prior = @selected[kind]
                rows = @assets[kind] || @repos
                replacement = rows.find { |row| row.values_at(:name, :repo) == prior.values_at(:name, :repo) }
                replacement ? @selected[kind] = replacement : @selected.delete(kind)
              end
            end
            refresh
          end

          # Presentation callbacks retain the original CLI arguments and cache
          # behavior. No native-only URL or asset acceptance rules live here.
          def repo_action(verb, *args)
            perform("repo #{verb}") do
              begin
                @actions.public_send("repo_#{verb}", *args)
              rescue StandardError => error
                append_log("[repo #{verb}] #{error.message}")
              ensure
                refresh_data
              end
            end
          end

          def asset_action(kind, verb, chosen, force)
            unless chosen
              append_log('[jinx.gui] No item selected ...')
              return
            end
            perform("#{verb} #{chosen[:name]}") do
              if verb == :info
                captured = []
                prior = Thread.current[:jinx_native_log]
                begin
                  Thread.current[:jinx_native_log] = proc { |text| captured << text.to_s.gsub(/<[^>]+>/, '') }
                  @actions.public_send("#{kind}_info", chosen[:name], chosen[:repo])
                rescue StandardError => error
                  captured << "Error: #{error.message}"
                ensure
                  Thread.current[:jinx_native_log] = prior
                end
                @mutex.synchronize { @info[kind] = captured.any? ? captured.join("\n") : 'No info available' }
              else
                @actions.public_send("#{kind}_#{verb}", chosen[:name], chosen[:repo], force: force)
                # The original refresh uses its existing full asset list here.
                @mutex.synchronize { @filters[kind] = nil }
              end
            end
          end

          # The original search runs in a worker and supersedes only an earlier
          # search for the same asset kind. Manifest retries must never block the
          # UI callback or prevent the window from closing.
          def search_assets(kind, text, clear: false)
            previous = @mutex.synchronize { @search_workers.delete(kind) }
            if previous&.alive?
              previous.kill
              previous.join
            end
            @mutex.synchronize do
              @search_revision[kind] += 1 if clear
              @search_text[kind] = clear ? '' : text
              @info[kind] = text.to_s.strip.empty? ? "Showing all #{kind}s..." : "Searching for '#{text.to_s.strip}'..."
            end
            if perform("Search #{kind}") { apply_search(kind, text) }
              @mutex.synchronize { @search_workers[kind] = @worker }
            end
          end

          def apply_search(kind, text)
            filter = text.to_s.strip
            rebuild_empty_assets(kind) if @mutex.synchronize { @assets[kind].empty? }
            @mutex.synchronize do
              @filters[kind] = filter.empty? ? nil : filter
              found = @assets[kind].select { |row| row[:name].match?(Regexp.new(Regexp.escape(filter), Regexp::IGNORECASE)) }
              @selected.delete(kind) unless found.include?(@selected[kind])
              @info[kind] = if filter.empty?
                              "Showing all #{kind}s..."
                            elsif found.empty?
                              "No #{kind}s found matching '#{filter}'"
                            else
                              "Found #{found.size} #{kind}(s) matching '#{filter}'\n\nSelect an item and click Info to see details"
                            end
            end
            refresh
          end

          def clear_log
            @mutex.synchronize { @logs = ["Log cleared at #{Time.now}"] }
            refresh
          end

          # Older catalogs exposed precomputed :scripts/:data arrays. Keep the
          # original wrappers instead of interpreting manifest types in the UI.
          def repo_assets(kind, manifest)
            method = kind == :script ? :scripts : :data
            @catalog.respond_to?(method) ? @catalog.public_send(method, manifest) : (manifest[method] || [])
          end

          # Both initial population and an empty-cache retry use the original
          # catalog wrappers and the same displayed status/filename conversion.
          def asset_rows(kind, manifest)
            repo_assets(kind, manifest).filter_map do |asset|
              name = File.basename(CGI.unescape(asset[:file].to_s))
              next if name.empty?
              { name: name, repo: manifest[:name].to_s, installed: installed_status(kind, name),
                modified: modified_status(kind, name, asset), updated: safe_ago(asset[:last_commit]) }
            end
          end

          def rebuild_empty_assets(kind)
            rows = []
            (@catalog.to_a rescue []).each do |repo|
              manifest = @mutex.synchronize { @manifest_cache[repo[:name].to_s] }
              unless manifest
                begin
                  manifest = manifest_with_retries(repo)
                  @mutex.synchronize { @manifest_cache[repo[:name].to_s] = manifest }
                rescue StandardError => error
                  append_log("[ERROR] Failed to load #{repo[:name]}: #{error.message}")
                  manifest = repo.merge(available: [])
                end
              end
              rows.concat(asset_rows(kind, manifest))
            end
            @mutex.synchronize { @assets[kind] = rows.sort_by { |row| [row[:name], row[:repo]] } }
          end

          # These accessors are read under the rendering mutex.
          def logs = @logs.dup
          def repos = @repos
          def assets(kind) = @assets.fetch(kind)
          def information(kind) = @info.fetch(kind)
          def search_text(kind) = @search_text.fetch(kind, '')
          def search_revision(kind) = @search_revision[kind]
          def busy? = @busy

          def safe_ago(ts)
          return '-' if ts.nil?
          ::Lich::Common::Jinx::Util.ago(ts) rescue '-'
        end

          def manifest_with_retries(repo, attempts: 3, delay: 1.0)
          last_e = nil
          attempts.times do |i|
            begin
              append_log("[DEBUG] Attempt #{i + 1}/#{attempts} to fetch manifest for #{repo[:name]}...")
              m = @catalog.manifest(repo)

              # Check if it's actually a valid manifest
              if m.is_a?(Hash)
                if m[:err]
                  # Repo.manifest returns error in :err field
                  append_log("[DEBUG] #{repo[:name]} returned error: #{m[:err]}")
                  return m # Return it anyway so we can handle it properly
                elsif m[:available].is_a?(Array)
                  append_log("[DEBUG] #{repo[:name]} manifest loaded successfully with #{m[:available].size} assets")
                  return m
                else
                  append_log("[DEBUG] #{repo[:name]} manifest missing :available array")
                  raise "invalid manifest structure - no :available array"
                end
              else
                append_log("[DEBUG] #{repo[:name]} returned non-Hash: #{m.class}")
                raise "manifest is not a Hash: #{m.class}"
              end
            rescue => e
              last_e = e
              append_log("[DEBUG] Attempt #{i + 1} failed: #{e.message}")
              sleep(delay) if i < attempts - 1
            end
          end
          append_log("[ERROR] All #{attempts} attempts failed for #{repo[:name]}")
          raise(last_e || "manifest failed after #{attempts} attempts")
        end

          def installed_status(kind, filename)
          dir =
            if kind == :script
              @directories.script_dir rescue nil
            else
              @directories.data_dir rescue nil
            end
          return 'unknown' unless dir.is_a?(String) && !dir.empty?
          File.exist?(File.join(dir, filename)) ? 'yes' : 'no'
        end

          def modified_status(kind, filename, asset)
          require 'digest/sha1'
          dir =
            if kind == :script
              @directories.script_dir rescue nil
            else
              @directories.data_dir rescue nil
            end
          return '-' unless dir.is_a?(String) && !dir.empty?
          path = File.join(dir, filename)
          return '-' unless File.exist?(path)
          begin
            remote_b64 = asset[:md5].to_s # upstream digest field is :md5 (base64 SHA1)
            return 'unknown' if remote_b64.empty?
            local_b64 = Digest::SHA1.base64digest(File.binread(path))
            (local_b64 == remote_b64) ? 'clean' : 'modified'
          rescue
            'unknown'
          end
        end

          private

          def append_log(value)
            return if value.to_s =~ /uberbar|dialogData|progressBar|anchor_left|Target Window|label id=/i
            return if value.to_s.strip.empty?
            @mutex.synchronize do
              return if @closed
              # The GTK text buffer counts the final empty line, and trims before
              # appending. Literal tags are log text, not HTML to strip.
              line_count = @logs.size + 1
              @logs.shift(line_count - 10_000 + 100) if line_count > 10_000
              @logs.concat(value.to_s.split("\n", -1))
            end
            refresh
          end

          def refresh
            Lich::WebUI.refresh(@page) if @page && !@mutex.synchronize { @closed }
          end

          # A single GTK append can temporarily exceed MAX_LOG_LINES: trimming
          # occurs on the next append. Group only wire records, never the stored
          # lines, and preserve the TextBuffer's final newline.
          def rendered_log_lines
            lines = logs + ['']
            bound = Lich::WebUI::Contract::BOUNDS.fetch(:log_lines)
            group_size = (lines.length.to_f / bound).ceil
            lines.each_slice(group_size).map { |group| Lich::WebUI::Contract.fragment_text(group.join("\n"), bound: :log_line) }
          end

          def render(tree)
            browser = self
            @mutex.synchronize do
              tree.tabs(key: 'tabs', names: %w[Log Repos Scripts Data], selected: 0, on: { select: proc {} }) do
                stack(slot: 'Log', fill: true, gap: 8, margin: { top: 8, left: 8, right: 8, bottom: 8 }) do
                  button(key: 'clear-log', label: 'Clear Log', on: { activate: proc {
                    browser.clear_log
                  } })
                  scroll(fill: true) { log(key: 'operation-log', lines: browser.send(:rendered_log_lines), max_lines: 10_000) }
                end
                stack(slot: 'Repos', fill: true, gap: 8, margin: { top: 8, left: 8, right: 8, bottom: 8 }) { browser.send(:render_repos, self) }
                stack(slot: 'Scripts', fill: true, gap: 8, margin: { top: 8, left: 8, right: 8, bottom: 8 }) { browser.send(:render_assets, self, :script) }
                stack(slot: 'Data', fill: true, gap: 8, margin: { top: 8, left: 8, right: 8, bottom: 8 }) { browser.send(:render_assets, self, :data) }
              end
            end
          end

          def render_table(tree, kind, records, columns)
            visible_pairs = records.each_with_index.filter_map do |record, index|
              next if @filters[kind] && !record[:name].downcase.include?(@filters[kind].downcase)
              ["#{kind}-#{index}", record]
            end
            sort = @table_sorts[kind]
            if sort
              visible_pairs = visible_pairs.each_with_index.sort do |(left, left_index), (right, right_index)|
                comparison = left.last[sort[:column].to_sym].to_s <=> right.last[sort[:column].to_sym].to_s
                comparison = -comparison if sort[:direction] == 'desc'
                comparison.zero? ? left_index <=> right_index : comparison
              end.map(&:first)
            end
            visible = visible_pairs.to_h
            # GTK's catalog stays complete in memory. Only the current table
            # page crosses the bounded WebUI contract; row keys still identify
            # original records for selection and CLI actions.
            limit = Lich::WebUI::Contract::BOUNDS.fetch(:table_rows)
            page_count = [(visible_pairs.size + limit - 1) / limit, 1].max
            page_index = [[@table_pages[kind], page_count - 1].min, 0].max
            @table_pages[kind] = page_index
            page_rows = visible_pairs.slice(page_index * limit, limit) || []
            selected_key = page_rows.to_h.key(@selected[kind])
            browser = self
            build_table = proc do |parent|
              parent.table(key: "#{kind}-table", columns: columns.each_with_index.map do |(key, label), index|
                             column = { key: key.to_s, label: label, sortable: true, resizable: true }
                             column[:width] = 0 unless index == columns.length - 1
                             column
                           end,
                           rows: page_rows.map { |key, row| { key: key, cells: columns.to_h { |column, _| [column.to_s, row[column]] } } },
                           fill: true, sortable: true, sort_mode: :lexical, grid_lines: :both, selection: :single,
                           selected: selected_key ? [selected_key] : [], **(sort ? { sort: sort } : {}),
                           on: { sort_change: proc { |event| browser.send(:change_table_sort, kind, event.payload) if page_count > 1 },
                                 selection_change: proc { |event|
                                   @mutex.synchronize { @selected[kind] = visible[event.payload[:rows].first] }
                                   refresh
                                 } })
            end
            if page_count > 1
              label = { repo: 'Repos', script: 'Scripts', data: 'Data' }.fetch(kind)
              tree.stack(key: "#{kind}-bounded-table", fill: true, gap: 0) do
                grid(key: "#{kind}-pages", cols: 3, homogeneous: false, expand_columns: [2], column_gap: 5) do
                  button(key: "#{kind}-previous-page", label: "Previous #{label}", disabled: page_index.zero?,
                         on: { activate: proc { browser.send(:turn_table_page, kind, -1) } })
                  text(key: "#{kind}-page-count", content: "#{label} page #{page_index + 1} of #{page_count}")
                  button(key: "#{kind}-next-page", label: "Next #{label}", disabled: page_index + 1 >= page_count,
                         on: { activate: proc { browser.send(:turn_table_page, kind, 1) } })
                end
                build_table.call(self)
              end
            else
              build_table.call(tree)
            end
          end

          def turn_table_page(kind, direction)
            @mutex.synchronize { @table_pages[kind] += direction }
            refresh
          end

          def change_table_sort(kind, sort)
            @mutex.synchronize { @table_sorts[kind] = sort }
            refresh
          end

          def render_assets(tree, kind)
            browser = self
            chosen = @selected[kind]&.dup
            tree.grid(key: "#{kind}-controls", cols: 7, homogeneous: false, expand_columns: [1], column_gap: 6) do
              search = text_input(key: "#{kind}-search-#{browser.search_revision(kind)}", placement: { column: 1, row: 1 }, value: browser.search_text(kind),
                search: true, placeholder: 'search by name... (empty = show all)',
                on: { submit: proc { |event| browser.search_assets(kind, event.submission[search.cid]) } })
              submit(search, [search])
              button(key: "#{kind}-search-button", placement: { column: 2, row: 1 }, label: 'Search', submit: [search],
                on: { activate: proc { |event| browser.search_assets(kind, event.submission[search.cid]) } })
              button(key: "#{kind}-clear", placement: { column: 3, row: 1 }, label: 'Clear', on: { activate: proc { browser.search_assets(kind, '', clear: true) } })
              force = checkbox(key: "#{kind}-force", placement: { column: 7, row: 1 }, label: 'Force overwrite', checked: false)
              %i[info install update].each_with_index do |verb, index|
                button(key: "#{kind}-#{verb}", placement: { column: index + 4, row: 1 }, label: verb.to_s.capitalize,
                  submit: verb == :info ? [] : [force],
                  on: { activate: proc { |event| browser.asset_action(kind, verb, chosen, verb == :info ? false : event.submission[force.cid]) } })
              end
            end
            tree.split(orientation: :horizontal, position_pixels: 700, resize_side: :first, fill: true, on: { move: proc {} }) do
              stack(slot: 'first', fill: true, gap: 0) do
                browser.send(:render_table, self, kind, browser.assets(kind),
                  [[:name, 'Name'], [:repo, 'Repo'], [:installed, 'Installed'], [:modified, 'Modified'], [:updated, 'Updated (ago)']])
              end
              group(slot: 'second', label: 'Information') do
                scroll(fill: true) do
                  # The original read-only TextView follows the application palette.
                  log(key: "#{kind}-info-text", lines: [Lich::WebUI::Contract.fragment_text(browser.information(kind), bound: :log_line)],
                      max_lines: 1, follow: false)
                end
              end
            end
          end

          def render_repos(tree)
            browser = self
            chosen = @selected[:repo]&.dup
            tree.grid(key: 'repo-controls', cols: 6, homogeneous: false, expand_columns: [1, 2], column_gap: 6) do
              name = text_input(key: 'repo-name', placement: { column: 1, row: 1 }, value: '', placeholder: 'repo name')
              url = text_input(key: 'repo-url', placement: { column: 2, row: 1 }, value: '', placeholder: 'https://...')
              button(key: 'repo-add', placement: { column: 3, row: 1 }, label: 'Add', submit: [name, url], on: { activate: proc { |event|
                repo_name, repo_url = event.submission[name.cid].to_s.strip, event.submission[url.cid].to_s.strip
                browser.repo_action(:add, repo_name, repo_url) unless repo_name.empty? || repo_url.empty?
              } })
              button(key: 'repo-change', placement: { column: 4, row: 1 }, label: 'Change URL', submit: [url], on: { activate: proc { |event|
                new_url = event.submission[url.cid].to_s.strip
                browser.repo_action(:change, chosen[:name], new_url) if chosen && !new_url.empty?
              } })
              button(key: 'repo-remove', placement: { column: 5, row: 1 }, label: 'Remove', on: { activate: proc {
                browser.repo_action(:rm, chosen[:name]) if chosen
              } })
              button(key: 'refresh', placement: { column: 6, row: 1 }, label: 'Refresh Manifests', on: { activate: proc {
                browser.perform('Refresh Manifests') { browser.refresh_data }
              } })
            end
            browser.send(:render_table, tree, :repo, browser.repos, [[:name, 'Name'], [:url, 'URL'], [:status, 'Status']])
          end
        end
      end
    end
  end
end

